        r = await aiCall({task: "news", auto: !manual, fast: true, maxTokens: 2000, schema: NEWS_SCHEMA,
          system: "You read course announcements for a student and pull out only concrete dates: new deadlines, tests, or changes to due dates. Ignore anything without a specific date. Return JSON only. If there is nothing, return an empty list.",
          parts: [{text: `Today is ${todayISO()} (${new Date().toLocaleDateString(undefined, {weekday: "long"})}).\nCourse: ${course ? course.name + (course.code ? " (" + course.code + ")" : "") : "unknown"}\nTasks already listed:\n${ts.map(t => `- ${t.title}: due ${t.due}${t.time ? " " + t.time : ""}`).join("\n") || "(none)"}\n\nAnnouncement "${n.title}" posted ${n.date ? String(n.date).slice(0, 10) : ""}:\n${n.text}`}]});
